const axios = require("axios");
const cheerio = require("cheerio");

const BASE_URL = "https://anichin.moe";
const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36";

let lastReq = 0;

async function fetchPage(url) {
  const now = Date.now();
  if (now - lastReq < 1500) {
    await new Promise((r) => setTimeout(r, 1500 - (now - lastReq)));
  }
  try {
    const res = await axios.get(url, {
      headers: {
        "User-Agent": UA,
        "Referer": BASE_URL + "/",
        "Accept": "text/html,*/*",
      },
      timeout: 30000,
    });
    lastReq = Date.now();
    return cheerio.load(res.data);
  } catch (e) {
    console.error("Gagal fetch:", url, e.message);
    return null;
  }
}

function parseList($) {
  const hasil = [];
  $(".bs .bsx, .listupd .bsx").each((_, el) => {
    const $el = $(el);
    const a = $el.find("a").first();
    const href = a.attr("href") || "";
    const img = $el.find("img").first();
    hasil.push({
      judul: $el.find(".tt h2, .tt h3, h2, h3").first().text().trim(),
      url: href.startsWith("http") ? href : BASE_URL + href,
      gambar: img.attr("src") || img.attr("data-src") || "",
      episode: $el.find(".epx, .ep, .newnime").first().text().trim(),
      tipe: $el.find(".typez, .type").first().text().trim(),
    });
  });
  return hasil;
}

function output(data) {
  console.log(JSON.stringify(data, null, 2));
}

async function halamanDepan() {
  const $ = await fetchPage(BASE_URL);
  if (!$) return output({ error: "Gagal fetch" });
  output(parseList($));
}

async function ongoing(jmlHal) {
  const semua = [];
  for (let i = 1; i <= jmlHal; i++) {
    const url = i > 1 ? `${BASE_URL}/ongoing/page/${i}/` : `${BASE_URL}/ongoing/`;
    const $ = await fetchPage(url);
    if (!$) break;
    const list = parseList($);
    if (!list.length) break;
    list.forEach((a) => (a.status = "Ongoing"));
    semua.push(...list);
  }
  output(semua);
}

