  const semua = [];
  for (let i = 1; i <= jmlHal; i++) {
    const url = i > 1 ? `${BASE_URL}/completed/page/${i}/` : `${BASE_URL}/completed/`;
    const $ = await fetchPage(url);
    if (!$) break;
    const list = parseList($);
    if (!list.length) break;
    list.forEach((a) => (a.status = "Completed"));
    semua.push(...list);
