async function cari(kata, jmlHal) {
  const semua = [];
  const q = encodeURIComponent(kata);
  for (let i = 1; i <= jmlHal; i++) {
    const url = i > 1 ? `${BASE_URL}/page/${i}/?s=${q}` : `${BASE_URL}/?s=${q}`;
    const $ = await fetchPage(url);
    if (!$) break;
    const list = parseList($);
    if (!list.length) break;
    semua.push(...list);
  }
  output(semua);
}

async function detail(url) {
  const $ = await fetchPage(url);
  if (!$) return output({ error: "Gagal fetch" });

  const info = {};
  $(".info-content .spe span, .single-info .spe span").each((_, el) => {
    const teks = $(el).text().trim();
    if (teks.includes(":")) {
      const [k, ...v] = teks.split(":");
      info[k.trim()] = v.join(":").trim();
    }
  });

  const genre = [];
  $(".info-content .genxed a, .genre-info a").each((_, el) => {
    genre.push($(el).text().trim());
  });
  if (genre.length) info.genre = genre;

  const episode = [];
  $(".eplister ul li").each((_, el) => {
    const link = $(el).find("a");
    const href = link.attr("href") || "";
    episode.push({
      episode: $(el).find(".epl-num").text().trim(),
      judul: $(el).find(".epl-title, .epl-sub").text().trim(),
      tanggal: $(el).find(".epl-date, .newnime").text().trim(),
      url: href.startsWith("http") ? href : BASE_URL + href,
    });
  });

  const img = $(".thumb img, .poster img, .ts-post-image").first();
  output({
    url,
    judul: $("h1.entry-title").first().text().trim(),
    judulAlternatif: (() => {
      const alt = [];
      $(".alter h1, .alt_title, .tosz h2").each((_, el) => {
        const t = $(el).text().trim();
        if (t) alt.push(t);
      });
      return alt;
    })(),
    gambar: img.attr("src") || img.attr("data-src") || "",
    sinopsis: $(".entry-content .spe p, .description .sinopsis, .sinopsis").first().text().trim(),
    info,
    episode,
    totalEpisode: episode.length,
  });
}

async function resolveHost(streamUrl) {
  try {
    const res = await axios.get(streamUrl, {
      headers: {
        "User-Agent": UA,
        "Referer": BASE_URL + "/",
      },
      timeout: 10000,
    });
    const $ = cheerio.load(res.data);

    let host = "";
    $("iframe").each((_, el) => {
      const src = $(el).attr("src") || "";
      if (src && !host) host = src;
    });

    if (host.includes("anichin-player")) {
      const res2 = await axios.get(host, {
        headers: {
          "User-Agent": UA,
          "Referer": streamUrl,
        },
        timeout: 10000,
      });
      const $2 = cheerio.load(res2.data);
      $2("iframe").each((_, el) => {
        const src = $2(el).attr("src") || "";
        if (src && !host.includes("ok.ru")) host = src;
      });
    }

    let videoUrl = "";
    $("video source, video").each((_, el) => {
      const src = $(el).attr("src") || "";
      if (src && !videoUrl) videoUrl = src;
    });

    if (!videoUrl) {
      $("script").each((_, el) => {
        const isi = $(el).html() || "";
        const m = isi.match(/file\s*:\s*["']([^"']+\.(m3u8|mp4))/);
        if (m && !videoUrl) videoUrl = m[1];
      });
    }

    let tipe = "other";
    if (host.includes("ok.ru")) tipe = "ok.ru";
    else if (host.includes("dailymotion")) tipe = "dailymotion";
    else if (host.includes("youtube")) tipe = "youtube";
    else if (host.includes("streamtape")) tipe = "streamtape";

    return {
      stream_url: streamUrl,
      host: host || videoUrl || "unknown",
      tipe,
    };
  } catch (e) {
    return {
      stream_url: streamUrl,
      host: "error: " + e.message,
    };
  }
}

async function episode(url) {
  const $ = await fetchPage(url);
  if (!$) return output({ error: "Gagal fetch" });

  const server = [];
  $(".player-embed iframe, .player iframe").each((_, el) => {
    const src = $(el).attr("src") || "";
    server.push(src.startsWith("http") ? src : BASE_URL + src);
  });

  const resolved = [];
  for (const s of server) {
    resolved.push(await resolveHost(s));
  }

  const download = [];
  $(".dlbox ul li, .download ul li").each((_, el) => {
    const a = $(el).find("a");
    download.push({
      kualitas: $(el).text().trim(),
      url: a.attr("href") || "",
    });
  });

  output({
    url,
    judul: $("h1.entry-title").first().text().trim(),
    server: resolved,
    download,
  });
}

async function genre(nama, jmlHal) {
  const semua = [];
  for (let i = 1; i <= jmlHal; i++) {
    const url = i > 1 ? `${BASE_URL}/genres/${nama}/page/${i}/` : `${BASE_URL}/genres/${nama}/`;
    const $ = await fetchPage(url);
    if (!$) break;
    const list = parseList($);
    if (!list.length) break;
    semua.push(...list);
  }
  output(semua);
}

async function daftarGenre() {
  const $ = await fetchPage(`${BASE_URL}/ongoing/`);
  if (!$) return output({ error: "Gagal fetch" });

  const genre = [];
  const sudah = new Set();
  $("a").each((_, el) => {
    const href = $(el).attr("href") || "";
    const teks = $(el).text().trim();
    if (href.includes("/genres/") && teks && !sudah.has(href)) {
      sudah.add(href);
      genre.push({
        nama: teks,
        slug: href.split("/genres/")[1]?.replace(/\/$/, "") || "",
      });
    }
  });
  output(genre);
}

async function main() {
  const arg = process.argv.slice(2);
  const cmd = arg[0];

  if (!cmd || cmd === "--help" || cmd === "-h") {
    output({
      command: ["home", "ongoing", "completed", "search", "detail", "episode", "genre", "genres"],
      contoh: [
        "node index.js home",
        "node index.js ongoing 5",
        'node index.js search "soul land"',
        "node index.js detail <url>",
        "node index.js episode <url>",
        "node index.js genre isekai 2",
        "node index.js genres",
      ],
    });
    return;
  }

  switch (cmd) {
    case "home":
      await halamanDepan();
      break;
    case "ongoing":
      await ongoing(parseInt(arg[1]) || 3);
      break;
    case "completed":
      await completed(parseInt(arg[1]) || 3);
      break;
    case "search":
      if (!arg[1]) return output({ error: "query wajib" });
      await cari(arg[1], parseInt(arg[2]) || 3);
      break;
    case "detail":
      if (!arg[1]) return output({ error: "url wajib" });
      await detail(arg[1]);
      break;
    case "episode":
      if (!arg[1]) return output({ error: "url wajib" });
      await episode(arg[1]);
      break;
    case "genre":
      if (!arg[1]) return output({ error: "nama genre wajib" });
      await genre(arg[1], parseInt(arg[2]) || 2);
      break;
    case "genres":
      await daftarGenre();
      break;
    default:
      output({ error: `command tidak dikenal: ${cmd}` });
  }
}

main();
